'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Reward, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './reward.css'

import { LockGlyph, StarGlyph, TickGlyph } from './glyphs'

/**
 * Reward: one thing a player can be given.
 *
 * A prize, a badge, a pack, a ticket, a discount code. It renders the object
 * and where that object is in its lifecycle, and it does nothing else. It does
 * not decide that a reward was earned, does not fetch it, does not claim it and
 * does not know what it is worth. Rewards are settled by the host (BDS-023 and
 * the attribute contract's "`rewarded` is a state without an event"), so every
 * lifecycle change arrives as a prop.
 *
 * Two drawings, from specimen 3d, on `data-gs-presentation`:
 *
 *   `card`    the reward in an inventory: prize art, the name, and a tail that
 *             is the state. Earned carries the claim control, available carries
 *             a progress track, locked a padlock, claimed a tick.
 *   `reveal`  the tap-to-reveal surface a host shows once: a pulsing question
 *             mark until it is pressed, then rays, the prize and its name.
 *             Only an earned reward has a reveal; any other state asked for it
 *             renders the card, because there is nothing to open.
 *
 * The lifecycle lives on `data-gs-reward-state` and deliberately not on
 * `data-gs-state`. `data-gs-state` is the settled outcome of something the
 * player did: set once, never revisited, and the three-things rule is defined
 * against exactly its three values. This one is host-driven and revisited over
 * time. Two concerns, two attributes. A locked reward is
 * `data-gs-reward-state="locked"` and never `data-gs-locked`, which stays a
 * control attribute.
 *
 * Revealing and claiming are the two things a player does here, so both are
 * real `<button>`s and Enter and Space work without any key handling of our
 * own. Which element is the button is decided below, once, so a host can never
 * be handed a button inside a button.
 */

export type RewardState = 'locked' | 'available' | 'earned' | 'claimed'

export type RewardPresentation = 'card' | 'reveal'

export interface RewardProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  /** The reward's id. Machine-readable, and what an inventory keys on. */
  id: string
  /** Where the reward is in its lifecycle. Host-driven, always. */
  state: RewardState
  /** The reward's name, as a player reads it. */
  label: string
  /** A supporting line. Never carries meaning the label does not. */
  detail?: string
  /**
   * What the reward is worth, as a number: 500 coins, 3 packs. Rendered beside
   * the name and carried machine-readably on `data-gs-value`.
   */
  value?: number
  /** The reveal has played. Only meaningful while the reward is earned. */
  revealed?: boolean
  /**
   * The prize art: an image, a Lottie slot, anything the host draws. It fills
   * the media slot on the card and the disc on an opened reveal. Without it the
   * slot is a quiet well, and the state's glyph sits in it.
   */
  media?: React.ReactNode
  /**
   * How far the player is towards an available reward, as `progress` out of
   * `max` (2 of 5 rounds), or as a fraction when `max` is omitted. Renders the
   * track on an available card and nothing anywhere else.
   */
  progress?: number
  max?: number
  /** Which of the two drawings. See the note at the top. */
  presentation?: RewardPresentation
  /** The words on the reveal before it opens, and on the card's control while it is waiting. */
  revealLabel?: string
  /** The word on the claim control. */
  claimLabel?: string
  /**
   * The player opening the reward. Fires only while the reward is earned and
   * unrevealed; at every other point in the lifecycle there is nothing to open.
   */
  onReveal?: (id: string) => void
  /**
   * The player claiming an earned, revealed reward. Supplying it renders the
   * claim control the drawing puts on the earned card. Claiming is settled by
   * the host: this reports the press and changes nothing.
   */
  onClaim?: (id: string) => void
}

/**
 * The words that go with the states, fixed by the attribute contract's
 * accessible-name table so that reward, inventory and everything downstream
 * cannot ship three vocabularies for one lifecycle.
 */
const STATE_LABEL: Record<RewardState, string> = {
  locked: 'locked',
  available: 'available',
  earned: 'earned',
  claimed: 'claimed',
}

const WAITING_LABEL = 'waiting'

/**
 * The waiting glyph. BDS-023 loops `motion.pulse` on an unrevealed reward, and
 * that is a `motion` element, so under reduced motion it stops dead. The
 * waiting state therefore also exists as this glyph and as the reward ring
 * around it, and `reward.test.tsx` asserts exactly that.
 */
const WAITING_GLYPH = '?'

const DEFAULT_REVEAL_LABEL = 'Tap to reveal'
const DEFAULT_CLAIM_LABEL = 'Claim'

/** The accessible name, in one place, because the inventory reads it too. */
export function rewardName({
  label,
  state,
  value,
  revealed,
}: Pick<RewardProps, 'label' | 'state' | 'value' | 'revealed'>): string {
  // What it is, then what it is worth, then what is true about it. The same
  // order `stat` uses, for the same reason: a screen reader user gets no fill,
  // no glyph and no motion, so the name has to carry all of it.
  const words: string[] = [label]
  if (value !== undefined) words.push(String(value))
  words.push(STATE_LABEL[state])
  if (state === 'earned' && !revealed) words.push(WAITING_LABEL)
  return words.join(', ')
}

/** 0 to 1, whatever the host passed. */
function fraction(progress: number, max: number | undefined): number {
  const ratio = max === undefined || max <= 0 ? progress : progress / max
  return Math.min(1, Math.max(0, ratio))
}

export function Reward({
  id,
  state,
  label,
  detail,
  value,
  revealed = false,
  media,
  progress,
  max,
  presentation: askedFor = 'card',
  revealLabel = DEFAULT_REVEAL_LABEL,
  claimLabel = DEFAULT_CLAIM_LABEL,
  onReveal,
  onClaim,
  className,
  onClick,
  ...rest
}: RewardProps) {
  // Earned and not yet opened. The only point in the lifecycle where opening
  // means anything.
  const waiting = state === 'earned' && !revealed
  // Earned and open. The only point where claiming means anything.
  const claimable = state === 'earned' && revealed
  // The reveal is a drawing of an earned reward. Asking for it on anything
  // else gets the card, and the attribute says which one actually rendered.
  const presentation: RewardPresentation = askedFor === 'reveal' && state === 'earned' ? 'reveal' : 'card'

  // The reveal, BDS-023 and the drawing's note beside the reward: "reveal:
  // motion.reveal 600ms + rays". It plays when `revealed` flips to true while
  // the reward is earned, and it plays by remounting the face with the
  // capability on it, so `replay` is the face's key. The previous value is
  // kept in state and compared during render, so the motion lands in the same
  // commit as the revealed state. A reward that mounts already revealed has
  // nothing to reveal and does not play it.
  const [wasRevealed, setWasRevealed] = React.useState(revealed)
  const [reveal, setReveal] = React.useState<{ replay: number } | null>(null)
  if (revealed !== wasRevealed) {
    setWasRevealed(revealed)
    if (revealed && state === 'earned') setReveal((last) => ({ replay: (last?.replay ?? 0) + 1 }))
  }
  const revealing = reveal !== null && revealed && state === 'earned'

  // Which element is the button, decided once.
  //
  // With `onReveal` alone the root is the button, as it always was: the whole
  // object opens, and it stays the same element after the reveal so the press
  // that revealed it does not destroy the focused node and drop focus to the
  // body, which is the exact moment a keyboard player most needs to stay put.
  //
  // With `onClaim` on a card, the root is a group and one control inside it is
  // the button: the claim control the drawing puts on the earned card, which
  // while the reward is still waiting is the reveal control instead. One
  // element for both jobs, for the same focus reason, and it sits outside the
  // face, which remounts to play the reveal. A root button holding a claim
  // button would be a button inside a button, which HTML forbids.
  const rootIsButton = onReveal !== undefined && (presentation === 'reveal' || onClaim === undefined)
  const innerControl =
    presentation === 'card' && onClaim !== undefined && (claimable || (waiting && onReveal !== undefined))

  const attributes = {
    ...rest,
    // No gs-action-type here, deliberately. The root's content is an object's
    // name, its value and a line of detail rather than the word on a control
    // you press to commit. Typing the whole subtree made arcade shout the
    // reward's name at weight 900. The claim control below carries the action
    // axis, because that is the one word here a player presses.
    className: ['gs-reward', rootIsButton ? 'gs-pressable' : null, className].filter(Boolean).join(' '),
    'data-gs-component': 'reward',
    'data-gs-reward': id,
    'data-gs-reward-state': state,
    'data-gs-presentation': presentation,
    // Boolean attributes are `true` or absent, never `"false"`: a selector for
    // the absence of `false` matches an element that does not exist.
    'data-gs-revealed': revealed ? 'true' : undefined,
    'data-gs-value': value,
    'aria-label': rewardName({ label, state, value, revealed }),
  }

  // The state's mark, or nothing. Available is the idle state and has none, as
  // the drawing has none: the progress track is what says available. Earned
  // once open is the star; locked the padlock; claimed the tick; waiting the
  // question mark, which is text rather than a drawing so that the reveal can
  // set it in the display face at forty points.
  const glyph =
    state === 'locked' ? <LockGlyph /> :
    state === 'claimed' ? <TickGlyph /> :
    waiting ? WAITING_GLYPH :
    state === 'earned' ? <StarGlyph filled /> :
    null

  // Emphasis, never motion: the glyph is the change that survives reduced
  // motion, and it is how the waiting state stays visible once the pulse has
  // stopped. The pulse rides inside it, on its own element, marked motion: the
  // drawing's own `motion.pulse` loop from motion.css, scale 1 to 1.06, which
  // stops entirely under reduced motion, which is why the glyph exists.
  const mark =
    glyph === null ? null : (
      <span
        className="gs-reward__glyph"
        data-gs-scope="reward" data-gs-part="glyph"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        {glyph}
        {waiting ? (
          <span
            className="gs-reward__pulse"
            data-gs-scope="reward" data-gs-part="pulse"
            data-gs-motion="pulse"
            data-gs-animates="motion"
            aria-hidden="true"
          />
        ) : null}
      </span>
    )

  // The rays behind a revealed reward, turning on the rays token. A loop, so
  // it is motion and stops under reduced motion, where the rays stay drawn and
  // still. Clipped by the face, behind its contents (reward.css). On the card
  // they turn only while the reveal is playing; on the reveal they are the
  // drawing's open state, so they are there whenever it is open.
  const rays = (
    <span
      className="gs-reward__rays"
      data-gs-scope="reward" data-gs-part="rays"
      data-gs-motion="rays"
      data-gs-animates="motion"
      aria-hidden="true"
    />
  )

  const track =
    state === 'available' && progress !== undefined ? (
      <span
        className="gs-reward__track"
        data-gs-scope="reward" data-gs-part="track"
        style={{ '--gs-progress': fraction(progress, max) } as React.CSSProperties}
      >
        <span className="gs-reward__fill" data-gs-scope="reward" data-gs-part="fill" data-gs-animates="motion" />
      </span>
    ) : null

  const control = innerControl ? (
    <button
      type="button"
      className="gs-reward__commit gs-action-type gs-pressable"
      data-gs-scope="reward" data-gs-part="commit"
      data-gs-animates="motion"
      // The control's own name says what it does to which reward, because the
      // root's name is hidden from it and "Claim" alone is not a name.
      aria-label={`${waiting ? revealLabel : claimLabel}, ${label}`}
      onClick={() => (waiting ? onReveal?.(id) : onClaim?.(id))}
    >
      {waiting ? revealLabel : claimLabel}
    </button>
  ) : null

  // Everything but the control is hidden: the root's label above is the
  // accessible name, and announcing the pieces again would read the reward
  // twice. The face is the surface the reveal plays on; it remounts to play.
  const face = (
    <span
      key={reveal?.replay}
      className="gs-reward__face"
      data-gs-scope="reward" data-gs-part="face"
      data-gs-motion={revealing ? 'reveal' : undefined}
      data-gs-animates="motion"
      aria-hidden="true"
    >
      {presentation === 'reveal' ? (
        revealed ? (
          <>
            {rays}
            <span className="gs-reward__media" data-gs-scope="reward" data-gs-part="media">
              {media ?? mark}
            </span>
            <span className="gs-reward__label" data-gs-scope="reward" data-gs-part="label">
              {label}
            </span>
          </>
        ) : (
          <>
            {mark}
            <span className="gs-reward__note" data-gs-scope="reward" data-gs-part="note">
              {revealLabel}
            </span>
          </>
        )
      ) : (
        <>
          {revealing ? rays : null}
          <span className="gs-reward__media" data-gs-scope="reward" data-gs-part="media">
            {media}
            {mark}
          </span>
          <span className="gs-reward__label" data-gs-scope="reward" data-gs-part="label">
            {label}
          </span>
          {value !== undefined ? (
            <span className="gs-reward__value gs-display-type" data-gs-scope="reward" data-gs-part="value">
              {value}
            </span>
          ) : null}
          {detail ? (
            <span className="gs-reward__detail" data-gs-scope="reward" data-gs-part="detail">
              {detail}
            </span>
          ) : null}
          {track}
        </>
      )}
    </span>
  )

  const inner = (
    <>
      {face}
      {control}
    </>
  )

  if (!rootIsButton) {
    return (
      <div {...attributes} role="group" onClick={onClick as React.MouseEventHandler<HTMLDivElement>}>
        {inner}
      </div>
    )
  }

  return (
    <button
      {...attributes}
      type="button"
      // Honest about what the press does. A claimed reward rendered inside an
      // inventory that passes one `onReveal` for the whole collection is still
      // a button, and telling a screen reader it can be pressed would be a lie.
      // aria-disabled rather than the native attribute: the reward stays
      // reachable, so it can still be read.
      aria-disabled={waiting ? undefined : true}
      onClick={(event) => {
        if (!waiting) {
          // A host may have overridden `type`, and a reward that is not waiting
          // must not submit a form.
          event.preventDefault()
          return
        }
        ;(onClick as React.MouseEventHandler<HTMLButtonElement> | undefined)?.(event)
        onReveal?.(id)
      }}
    >
      {inner}
    </button>
  )
}

/* Reward. Every value comes from a token; nothing here is a literal colour.

   Specimen 3d draws this, and design/twins/3d.json measures ours against it
   declaration by declaration: the card in four states, and the reveal. Where a
   value below is not the drawing's, the twins file says which token was the
   nearest and why, so a difference reads as a decision rather than a miss.

   The motion is motion.css's, which ships with @gamestage/tokens: the pulse,
   the reveal and the rays are asked for with data-gs-motion and this file
   only says where each one sits. */

/* -- the card ------------------------------------------------------------- */
/* A surface with a 3px outline at the large radius, padded 12, its parts
   stacked at 8: art, name, and a tail that is the state. Left-aligned text,
   as drawn. The card takes the width it is given; an inventory gives it a
   column. */
.gs-reward {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  inline-size: 100%;
  margin: 0;
  padding: var(--gs-space-3);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
  text-align: start;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  /* Emphasis: the state changes the fill and the outline, and a state change a
     player only sees if they can see animation is not a state change. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    border-color var(--gs-motion-emphasis) ease-out,
    box-shadow var(--gs-motion-emphasis) ease-out;
}

/* Only a reward that can be opened invites a press. */
.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]) { cursor: pointer; }
.gs-reward[aria-disabled='true'] { cursor: default; }

.gs-reward:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}

/* -- the face ------------------------------------------------------------- */
/* The surface the reveal plays on: it holds the art, the words and the track,
   stacked at the card's gap, and it remounts with data-gs-motion="reveal" when
   the reward opens. The rays behind an open reward are drawn by motion.css and
   turned by the rays token; the face clips them and paints them behind its own
   contents. It is a stacking context, so a negative z-index lands between the
   face's background and its glyph rather than behind the whole reward. */
.gs-reward__face {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  overflow: hidden;
  border-radius: inherit;
}

.gs-reward__rays {
  z-index: -1;
}

/* -- the art slot --------------------------------------------------------- */
/* 64 tall at the small radius, the host's picture inside it. Empty, it is a
   dark well: the drawing draws the locked slot that way and gives the other
   three a striped placeholder that stands for art not yet supplied, which is
   the designer's note and not the component's. */
.gs-reward__media {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  block-size: var(--gs-size-icon-hero);
  overflow: hidden;
  border-radius: var(--gs-radius-sm);
  background: var(--gs-color-scrim);
}

.gs-reward__media > img,
.gs-reward__media > picture,
.gs-reward__media > video {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

/* -- the glyph ------------------------------------------------------------ */
/* Centred in the art slot at the control icon size. Each state restyles it
   below; the drawing puts the padlock and the tick here. */
.gs-reward__glyph {
  position: absolute;
  inset: 0;
  margin: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-size-icon-control);
  font-weight: var(--gs-type-stat-font-weight);
  line-height: 1;
  color: var(--gs-color-ink-secondary);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. It
     is how a player who sees no movement still sees the state change. */
  transition: color var(--gs-motion-emphasis) ease-out,
              opacity var(--gs-motion-emphasis) ease-out;
}

/* -- the words ------------------------------------------------------------ */
/* The name: the interface face, heavy, sentence case, no tracking. The
   drawing sets 800 13px; type.label is 800 12px and the nearest role. */
.gs-reward__label {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
}

/* The face clips (overflow: hidden, for the rays) and the words start on its
   edge, so a round first letter lost its left overshoot: "Gold Helmet" drew
   with a notched G. A pixel of padding either side keeps the glyph whole. */
.gs-reward__label,
.gs-reward__detail {
  padding-inline: 1px;
}

.gs-reward__value {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  text-shadow: none;
}

/* The line under the name, in the caption face and the secondary ink. */
.gs-reward__detail {
  font-family: var(--gs-type-caption-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  color: var(--gs-color-ink-secondary);
}

/* -- the claim control ---------------------------------------------------- */
/* A 40px primary at the small radius with the 3px outline and a shelf: the
   drawing's Claim. Type is the action axis at the figure size, one property
   borrowed, because a 19px action face does not fit a 180px card. */
.gs-reward__commit {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  block-size: var(--gs-size-control-small);
  margin: 0;
  padding: 0 var(--gs-space-3);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-sm);
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
  box-shadow: var(--gs-depth-raised);
  font-size: var(--gs-type-figure-font-size);
  line-height: 1;
  cursor: pointer;
}

.gs-reward__commit:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}

/* -- the progress track --------------------------------------------------- */
/* Inset, per the depth rule: the track is the hole the fill sits in. The
   drawing draws it 12 tall; the library's tracks are the utility icon size. */
.gs-reward__track {
  --gs-progress: 0;
  position: relative;
  display: block;
  overflow: hidden;
  block-size: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
}

.gs-reward__fill {
  display: block;
  block-size: 100%;
  inline-size: calc(var(--gs-progress) * 100%);
  border-radius: inherit;
  background: var(--gs-color-positive);
  /* BDS-022: the fill runs over motion.fill. Motion only. */
  transition: inline-size var(--gs-motion-fill) ease-out;
}

/* -- the lifecycle -------------------------------------------------------- */
/* Each state changes the surface, the glyph and the text at once. A state that
   is only a colour fails the accessibility stage, and rightly. */

/* Locked: it exists and it is not yours yet. The outline colour as the fill,
   a dashed muted outline, muted ink, no depth, a padlock in the well. */
.gs-reward[data-gs-reward-state='locked'] {
  background: var(--gs-color-edge);
  border-style: dashed;
  border-color: var(--gs-color-muted);
  color: var(--gs-color-muted);
  box-shadow: var(--gs-depth-flat);
}

.gs-reward[data-gs-reward-state='locked'] .gs-reward__glyph,
.gs-reward[data-gs-reward-state='locked'] .gs-reward__detail {
  color: inherit;
}

/* Available: reachable, not yet taken. It stands on a shelf and carries the
   track. No glyph: this is the idle state, and the track is what says it. */
.gs-reward[data-gs-reward-state='available'] {
  box-shadow: var(--gs-depth-raised);
}

/* Earned: the ring and glow from the three-things table, and once open the
   reward mark in the corner of the art and the claim control underneath. */
.gs-reward[data-gs-reward-state='earned'] {
  box-shadow: var(--gs-depth-reward);
}

.gs-reward[data-gs-reward-state='earned'][data-gs-revealed] .gs-reward__glyph {
  inset: var(--gs-space-1) var(--gs-space-1) auto auto;
  margin: 0;
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
  font-size: var(--gs-size-icon-utility);
  color: var(--gs-color-reward-solid);
}

/* Claimed: it happened, it is done, it stops shouting. Three quarters opacity,
   no depth, and the tick in a positive disc on the art. */
.gs-reward[data-gs-reward-state='claimed'] {
  opacity: 0.75;
  box-shadow: var(--gs-depth-flat);
}

.gs-reward[data-gs-reward-state='claimed'] .gs-reward__glyph {
  box-sizing: border-box;
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  background: var(--gs-color-positive);
  font-size: var(--gs-size-icon-utility);
  color: var(--gs-color-on-bright);
}

/* -- waiting to be opened ------------------------------------------------- */
/* The pulse is the only motion here and it stops dead under reduced motion, so
   waiting is carried by the glyph and the ring as well. Both of those are
   emphasis and both survive. This is the rule BDS-023 exists to state. The
   loop itself is motion.css's: the ring carries data-gs-motion="pulse" and
   the drawing's own keyframe scales it 1 to 1.06 over the pulse token. */
.gs-reward[data-gs-reward-state='earned']:not([data-gs-revealed]) .gs-reward__glyph {
  color: var(--gs-color-reward-solid);
}

.gs-reward__pulse {
  position: absolute;
  inset: calc(-1 * var(--gs-stroke-ui));
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-reward);
  pointer-events: none;
}

/* -- the reveal ----------------------------------------------------------- */
/* The tap-to-reveal surface: a raised slab at the largest radius, centred,
   holding a question mark in a disc and the instruction under it. The whole
   slab is the button and travels the press distance on its shelf. */
.gs-reward[data-gs-presentation='reveal'] {
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-3);
  padding: var(--gs-space-8) var(--gs-space-4);
  overflow: hidden;
  /* The open state's rays sit at a negative z-index; the slab is its own
     stacking context so they paint over its fill and under its contents. */
  isolation: isolate;
  border-radius: var(--gs-radius-xl);
  background: var(--gs-color-surface-raised);
  box-shadow: var(--gs-depth-raised);
  text-align: center;
}

.gs-reward[data-gs-presentation='reveal'] .gs-reward__face {
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-3);
  overflow: visible;
}

/* The disc: the surface colour on a 4px outline, the question mark in the
   display face and the reward colour with the display shadow. The pulse rides
   inside it and scales the ring, not the glyph. */
.gs-reward[data-gs-presentation='reveal'] .gs-reward__glyph {
  position: relative;
  inset: auto;
  margin: 0;
  box-sizing: border-box;
  inline-size: var(--gs-size-action-large);
  block-size: var(--gs-size-action-large);
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-selected) solid var(--gs-color-edge);
  background: var(--gs-color-surface);
  font-family: var(--gs-type-score-font-family);
  font-size: var(--gs-type-score-font-size);
  font-weight: var(--gs-type-score-font-weight);
  color: var(--gs-color-reward-solid);
  text-shadow: var(--gs-type-display-shadow);
}

.gs-reward[data-gs-presentation='reveal'] .gs-reward__pulse {
  inset: calc(-1 * var(--gs-stroke-selected));
}

/* "Tap to reveal": the figure face, uppercase as drawn. */
.gs-reward__note {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  text-transform: uppercase;
  color: var(--gs-color-ink);
}

/* Open: the slab goes dark and flat, rays turn behind a prize disc on the
   reward ring, and the name lands under it in the title face with the
   display shadow. The rays are clipped by the slab rather than the face, so
   they fill the drawing's whole open surface. */
.gs-reward[data-gs-presentation='reveal'][data-gs-revealed] {
  background: var(--gs-color-edge);
  box-shadow: var(--gs-depth-flat);
}

.gs-reward[data-gs-presentation='reveal'][data-gs-revealed] .gs-reward__face {
  position: static;
}

.gs-reward[data-gs-presentation='reveal'] .gs-reward__media {
  position: relative;
  box-sizing: border-box;
  inline-size: var(--gs-size-action-large);
  block-size: var(--gs-size-action-large);
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-selected) solid var(--gs-color-edge);
  background: var(--gs-color-reward);
  box-shadow: var(--gs-depth-reward);
  color: var(--gs-color-on-bright);
}

.gs-reward[data-gs-presentation='reveal'][data-gs-revealed] .gs-reward__glyph {
  inline-size: auto;
  block-size: auto;
  border: 0;
  background: none;
  font-size: var(--gs-size-icon-control);
  color: var(--gs-color-on-bright);
  text-shadow: none;
}

.gs-reward[data-gs-presentation='reveal'] .gs-reward__label {
  position: relative;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  text-transform: uppercase;
  text-shadow: var(--gs-type-display-shadow);
}
